 function clearProps(){held=turning=drag=null;if(builtPhase===phase){surfaces.remove('campaign-canopy');surfaces.remove('campaign-canopy-top')}props.length=0;if(!root.children.length||builtPhase===phase)disposeRoot(root);else marks.forEach(mark=>mark.visible=false);root=new THREE.Group();const [dx,dz]=offset();root.position.set(dx,0,dz);world.add(root);roots.push(root);builtPhase=phase;marks.length=0;nurseryShade=nurseryLight=pondShade=pondLight=pondWater=pondSourceWater=pondInletWater=pantrySourceWater=pantryWater=pantryShade=pantryLight=finalWater=wildlife=null;bubbles=[];festivalFlowers=[]}
