 function pointerDown(e,raycaster){if(!active||!ui.hidden||phase==='water'||phase==='complete')return false;const hits=raycaster.intersectObjects(props.map(p=>p.root),true);if(!hits.length)return false;let o=hits[0].object;while(o&&!o.userData.forestProp)o=o.parent;const p=byId(o?.userData.forestProp);if(!p||!near(p))return false;if(phase==='sun'&&p.id==='screen'&&(!flags.sunA||!flags.sunB)){tell('Clear both fallen branches before turning the screen.');return true}if(p.kind==='inspect'){if(flags.pantryWater&&flags.pantryLight)mark('seeds');else tell('Restore sunlight and water to these seed plants first.');openInspection('seeds');return true}drag={id:e.pointerId,p,x:e.clientX,z:e.clientY,start:p.angle,offset:new THREE.Vector2()};if(p.kind==='move'||p.kind==='vine'){const hit=raycaster.ray.intersectPlane(plane,tmp),[dx,dz]=offset();if(hit)drag.offset.set(p.root.position.x-hit.x+dx,p.root.position.z-hit.z+dz)}held=turning=null;return true}
